// Encryption format (Signal-compatible):
//    - Algorithm: AES-256-CBC + HMAC-SHA256 (Encrypt-then-MAC)
//    - Key: 64 bytes = \[AES key (32 bytes)\] + \[MAC key (32 bytes)\]
//    - Ciphertext format: \[IV (16 bytes)\] + \[AES-CBC output\] + \[HMAC-SHA256 (32 bytes)\]
//    - Padding: Log-bucketed to prevent size-based content inference
//    - Digest: SHA-256 of entire ciphertext (IV + encrypted + MAC)
//
// There is no per-chunk (incremental) MAC: every file, whatever its size,
// carries only the single trailing HMAC-SHA256 above.
//
// Flow:
//    1. Client generates random 64-byte key (split into AES + MAC keys)
//    2. Client pads plaintext to log-bucket size
//    3. Client encrypts: IV || AES-CBC(padded_plaintext) || HMAC-SHA256
//    4. Client computes digest = SHA-256(ciphertext)
//    5. Client uploads ciphertext to CDN (gets cdn_key)
//    6. Client embeds this pointer in E2E encrypted message
//    7. Recipient downloads from cdn_key, verifies digest, decrypts with key

#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct AttachmentPointer {
    /// CDN key/path for downloading the encrypted blob
    #[prost(string, tag="1")]
    pub cdn_key: ::prost::alloc::string::String,
    /// Encryption key: 64 bytes = \[AES-256 key (32)\] + \[HMAC-SHA256 key (32)\]
    /// Generated randomly per attachment. NEVER sent to server.
    #[prost(bytes="vec", tag="2")]
    pub encryption_key: ::prost::alloc::vec::Vec<u8>,
    /// SHA-256 digest of entire ciphertext for integrity verification (32 bytes)
    /// Computed as: SHA256(IV || AES-CBC-ciphertext || HMAC)
    #[prost(bytes="vec", tag="3")]
    pub digest: ::prost::alloc::vec::Vec<u8>,
    /// Size of original plaintext file in bytes (before padding)
    #[prost(uint64, tag="4")]
    pub plaintext_size: u64,
    /// MIME type of the original file
    #[prost(string, tag="5")]
    pub content_type: ::prost::alloc::string::String,
    /// Original filename
    #[prost(string, tag="6")]
    pub file_name: ::prost::alloc::string::String,
    /// Thumbnail for images/videos, delivered as a SEPARATE small CDN object
    /// (NOT inline) so the pointer stays under the sealed-DM padding budget on
    /// every transport. Encrypted with the same AES-CBC+HMAC scheme as the main
    /// blob; decryption material below. Empty for non-media attachments.
    #[prost(string, tag="7")]
    pub thumbnail_cdn_key: ::prost::alloc::string::String,
    /// Thumbnail dimensions
    #[prost(uint32, tag="8")]
    pub thumbnail_width: u32,
    #[prost(uint32, tag="9")]
    pub thumbnail_height: u32,
    /// Blur hash for progressive loading (unencrypted, safe metadata)
    #[prost(string, tag="10")]
    pub blur_hash: ::prost::alloc::string::String,
    /// Media dimensions (for images/videos)
    #[prost(uint32, tag="11")]
    pub width: u32,
    #[prost(uint32, tag="12")]
    pub height: u32,
    /// Duration in milliseconds (for audio/video)
    #[prost(uint64, tag="13")]
    pub duration_ms: u64,
    /// Voice note flag
    #[prost(bool, tag="14")]
    pub voice_note: bool,
    // ==== Thumbnail sidecar decryption material (see thumbnail_cdn_key) ====

    /// 64-byte key (\[AES-256 (32)\] + \[HMAC-SHA256 (32)\]) for the thumbnail blob.
    #[prost(bytes="vec", tag="15")]
    pub thumbnail_key: ::prost::alloc::vec::Vec<u8>,
    /// SHA-256 digest of the thumbnail ciphertext, for integrity verification.
    #[prost(bytes="vec", tag="16")]
    pub thumbnail_digest: ::prost::alloc::vec::Vec<u8>,
    /// Size of encrypted blob in bytes (ciphertext size, not plaintext)
    #[prost(uint64, tag="17")]
    pub ciphertext_size: u64,
    /// SHA-256 hash of original plaintext (hex string, for deduplication)
    #[prost(string, tag="18")]
    pub plaintext_hash: ::prost::alloc::string::String,
    /// Audio waveform visualization data (32 samples, 0-255 amplitude)
    /// Generated sender-side, displayed immediately by receiver without download.
    /// Only present for audio attachments (voice notes, audio files).
    #[prost(bytes="vec", tag="19")]
    pub waveform: ::prost::alloc::vec::Vec<u8>,
    /// Plaintext size of the thumbnail in bytes, needed to strip padding after
    /// decrypting the thumbnail sidecar blob.
    #[prost(uint32, tag="20")]
    pub thumbnail_plaintext_size: u32,
}
