// =============================================================================
// SavedMessageSync: Sync saved messages (Note to Self) across devices
// =============================================================================
//
// Follows Signal's approach: saved messages are sent as sync messages to
// the user's own devices via Signal Protocol device sessions. No special
// encryption key — Signal Protocol provides forward secrecy.

//
// One SavedMessageSync is a FULL SNAPSHOT of one Saved record as the sending
// device stores it: creation, edit and pin/unpin all send the same shape, and
// a receiving device upserts it. A snapshot that arrives before the record it
// describes creates the record; a replayed or reordered one is idempotent, as
// each mutable part carries its own clock (`edited_at`, `pin_changed_at`) and
// a receiver applies a part only when that clock is newer than what it holds.
// The record's identity (`message_id`, `sent_at`) never changes.
//
// Fields 1-4 are what the first version carried; a receiver that only knows
// those stores the body or skips an id it already has, never an empty row.

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct SavedMessageSync {
    /// Current message text (the edited body once edited)
    #[prost(string, tag="1")]
    pub text: ::prost::alloc::string::String,
    /// Message ID (UUID, same across all devices)
    #[prost(string, tag="2")]
    pub message_id: ::prost::alloc::string::String,
    /// When the message was sent (nanoseconds since epoch)
    #[prost(fixed64, tag="3")]
    pub sent_at: u64,
    /// Attachment IDs (CDN keys of the attachments below)
    #[prost(string, repeated, tag="4")]
    pub attachment_ids: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// The attachments themselves: CDN key, decryption material, metadata and
    /// thumbnail sidecar, so the receiving device can fetch and show them.
    #[prost(message, repeated, tag="5")]
    pub attachments: ::prost::alloc::vec::Vec<AttachmentPointer>,
    /// Reply context when this record quotes another Saved record:
    /// `quoted_message_id` is the quoted record's real id (the receiver's
    /// `reply_to`, whether or not it holds that record yet), `quote.id` is its
    /// `sent_at` when the sender still holds it (0 otherwise), `quote.text` the
    /// stored preview, `quote.attachments\[0\]` the stored thumbnail, and
    /// `author_aci` is our own account.
    #[prost(message, optional, tag="6")]
    pub quote: ::core::option::Option<Quote>,
    #[prost(string, tag="10")]
    pub quoted_message_id: ::prost::alloc::string::String,
    /// When the body was last edited (nanoseconds since epoch); 0 = never.
    /// A receiver replaces its body only when this is newer than its own.
    #[prost(fixed64, tag="7")]
    pub edited_at: u64,
    /// Current pin state and when it last changed (nanoseconds since epoch;
    /// 0 = never pinned or unpinned). A receiver applies `pinned` only when
    /// `pin_changed_at` is newer than the last change it applied, pin or unpin,
    /// so a reordered old pin cannot undo a newer unpin.
    #[prost(bool, tag="8")]
    pub pinned: bool,
    #[prost(fixed64, tag="9")]
    pub pin_changed_at: u64,
}
/// =============================================================================
/// SyncSent: a copy of a message WE sent, synced to our OWN other devices
/// =============================================================================
///
/// Signal's SyncMessage.Sent equivalent. When a message is sent from one of our
/// devices, the self-sync copy delivered to our other devices is wrapped in this
/// message rather than shipped as the bare DataMessage the recipient got.
///
/// The bare DataMessage carries no record of who it was for: the self-copy's only
/// sender identity is our own sealed-sender certificate, so a receiving device
/// files it under a conversation with OURSELVES, attributed to us — never as our
/// outgoing message to the real recipient. That was bug F8 (see VALIDATED.md).
///
/// SyncSent closes the gap exactly as Signal's Sent.destination does: it carries
/// the real recipient explicitly, so our other devices bucket the message into
/// the correct conversation as OUTGOING.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct SyncSent {
    /// The real recipient of the original message (NOT us). Our other devices
    /// bucket the message into the conversation with this user. Mirrors Signal's
    /// Sent.destination.
    #[prost(string, tag="1")]
    pub destination_user_id: ::prost::alloc::string::String,
    /// When the original message was sent (nanoseconds since epoch). Mirrors
    /// Signal's Sent.timestamp.
    #[prost(fixed64, tag="2")]
    pub timestamp: u64,
    /// The content that was sent. Mirrors Signal's Sent.message (a DataMessage).
    #[prost(message, optional, tag="3")]
    pub message: ::core::option::Option<DataMessage>,
    /// Original send-time recipients, copied to our devices for receipt validation.
    #[prost(message, repeated, tag="4")]
    pub receipt_targets: ::prost::alloc::vec::Vec<SyncSentReceiptTarget>,
}
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct SyncSentReceiptTarget {
    #[prost(string, tag="1")]
    pub user_id: ::prost::alloc::string::String,
    #[prost(uint32, tag="2")]
    pub device_id: u32,
}
